import type { BehaviorStepContext } from '@thirdlight/runtime';
import { scale } from './ui.tsx';

export default {
  prepare() {
    return {};
  },

  instantiate() {
    return {};
  },

  step(_state: unknown, ctx: BehaviorStepContext): void {
    ctx.emit({ kind: 'control_move', value: scale(ctx.properties.speed as number) });
  },

  dispose() {},
};
